def patch(path, delta_path, backup, raise_errors, debug):
    try:
        content = load_path_content(path)
        delta = load_path_content(delta_path, file_type=delta_path.split('.')[-1])

        if backup:
            save_content_to_path(content, f"{path}.bak")

        patched_content = delta.apply(content)
        save_content_to_path(patched_content, path)

    except Exception as e:
        if debug:
            raise
        elif raise_errors:
            sys.exit(str(e))
